import ast, json, random, copy
from pathlib import Path
from types import SimpleNamespace
from collections import Counter

# This facade executes the source integer/index methods only.
# It is not a numerical substitute for PyTorch, CUDA or autograd.
class T:
    def __init__(self, rows):
        self.rows=[list(row) for row in rows]
        self.shape=(len(self.rows),len(self.rows[0]) if self.rows else 0)
        assert all(len(row)==self.shape[1] for row in self.rows)
        self.ndim=2;self.device='facade'
    def binary(self,other,fn):
        if not isinstance(other,T):
            return T([[fn(v,other) for v in row] for row in self.rows])
        b=max(self.shape[0],other.shape[0]);l=max(self.shape[1],other.shape[1])
        assert self.shape[0] in [1,b] and other.shape[0] in [1,b]
        assert self.shape[1] in [1,l] and other.shape[1] in [1,l]
        return T([[fn(self.rows[i%self.shape[0]][j%self.shape[1]],other.rows[i%other.shape[0]][j%other.shape[1]]) for j in range(l)] for i in range(b)])
    def __add__(self,o):return self.binary(o,lambda a,b:a+b)
    def __sub__(self,o):return self.binary(o,lambda a,b:a-b)
    def __rsub__(self,o):return self.binary(o,lambda a,b:b-a)
    def __mul__(self,o):return self.binary(o,lambda a,b:a*b)
    def __lt__(self,o):return self.binary(o,lambda a,b:a<b)
    def __gt__(self,o):return self.binary(o,lambda a,b:a>b)
    def __eq__(self,o):return self.binary(o,lambda a,b:a==b)
    def __ne__(self,o):return self.binary(o,lambda a,b:a!=b)
    def __and__(self,o):return self.binary(o,lambda a,b:bool(a) and bool(b))
    def __or__(self,o):return self.binary(o,lambda a,b:bool(a) or bool(b))
    def __invert__(self):return T([[not v for v in row] for row in self.rows])
    def __bool__(self):raise AssertionError('Ambiguous facade tensor truth')
    def __getitem__(self,key):
        assert isinstance(key,tuple) and len(key)==2
        a,b=key
        return T([row[b] for row in self.rows[a]])
    def bool(self):return T([[bool(v) for v in row] for row in self.rows])
    def long(self):return T([[int(v) for v in row] for row in self.rows])
    def clamp_min(self,v):return T([[max(v,x) for x in row] for row in self.rows])
    def clamp_max(self,v):return T([[min(v,x) for x in row] for row in self.rows])
    def remainder(self,o):return self.binary(o,lambda a,b:a%b)
    def expand(self,b,l):
        if b==-1:b=self.shape[0]
        if l==-1:l=self.shape[1]
        return T([[self.rows[i%self.shape[0]][j%self.shape[1]] for j in range(l)] for i in range(b)])
    def gather(self,dim,index):
        assert dim==1 and self.shape[0]==index.shape[0]
        return T([[self.rows[i][j] for j in row] for i,row in enumerate(index.rows)])
    def scatter(self,dim,index,values):
        assert dim==1
        result=T(self.rows)
        for i,row in enumerate(index.rows):
            for j,k in enumerate(row):result.rows[i][k]=values.rows[i][j]
        return result
    def cumsum(self,dim):
        assert dim==1;out=[]
        for row in self.rows:
            total=0;res=[]
            for x in row:total+=x;res.append(total)
            out.append(res)
        return T(out)
    def sum(self,dim,keepdim=False):
        assert dim==1 and keepdim
        return T([[sum(row)] for row in self.rows])
    def min(self,dim,keepdim=False):
        assert dim==1 and keepdim
        return SimpleNamespace(values=T([[min(row)] for row in self.rows]))
    def argmin(self,dim,keepdim=False):
        assert dim==1 and keepdim
        return T([[min(range(len(row)),key=row.__getitem__)] for row in self.rows])
class V:
    def __init__(self,row):self.row=row
    def unsqueeze(self,dim):
        assert dim==0
        return T([self.row])
class Torch:
    long='long';bool='bool'
    def arange(self,n,**kw):return V(list(range(n)))
    def zeros_like(self,x,**kw):return T([[0]*x.shape[1] for _ in x.rows])
    def ones_like(self,x,**kw):return T([[1]*x.shape[1] for _ in x.rows])
    def full_like(self,x,n,**kw):return T([[n]*x.shape[1] for _ in x.rows])
    def where(self,cond,a,b):
        if not isinstance(a,T):a=self.full_like(cond,a)
        if not isinstance(b,T):b=self.full_like(cond,b)
        shape=(max(cond.shape[0],a.shape[0],b.shape[0]),max(cond.shape[1],a.shape[1],b.shape[1]))
        aa=a.expand(*shape);bb=b.expand(*shape);cc=cond.expand(*shape)
        return T([[aa.rows[i][j] if c else bb.rows[i][j] for j,c in enumerate(row)] for i,row in enumerate(cc.rows)])
    def argsort(self,x,dim,stable):
        assert dim==1 and stable
        return T([sorted(range(len(row)),key=row.__getitem__) for row in x.rows])
    def cat(self,items,dim):
        assert dim==1
        return T([sum([t.rows[i] for t in items],[]) for i in range(items[0].shape[0])])
torch=Torch()
def harness(file):
    parsed=ast.parse(Path(file).read_text())
    cls=next(n for n in parsed.body if isinstance(n,ast.ClassDef))
    methods=[n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name in ['_history_layout','_path_sources','_cyclic_sources']]
    tree=ast.fix_missing_locations(ast.Module(body=[ast.ClassDef(name='Harness',bases=[],keywords=[],body=methods,decorator_list=[])],type_ignores=[]))
    ns={'torch':torch};exec(compile(tree,file,'exec'),ns)
    h=ns['Harness']();h.num_tasks=4
    h.item_fields=['item_id','cate_id','campaign_id','customer_id','brand','price_bucket'];h.action_field='action'
    return h
new=harness('candidate.py');old=harness('history_g1_r0061_canonical_ring.py')
names=new.item_fields+[new.action_field]
rng=random.Random(62001)
checks=Counter();distinguish=Counter()
def tuples(item,tasks,b,valid_positions):
    return [tuple(item[n].rows[b][j] for n in names)+tuple(t.rows[b][j] for t in tasks) for j in valid_positions]
def execute(h,layout,item,mask,tasks):
    h.history_layout=layout
    out,elig=h._history_layout(item,mask,tasks)
    return out,elig
def compare(a,b):
    return all(a[0][n].rows==b[0][n].rows for n in names) and all(x.rows==y.rows for x,y in zip(a[1],b[1]))
lengths=[0,1,2,3,9,10,11,16,20,21,29,30,31,39,40,64,99,100]
for iteration in range(36):
    count=lengths[iteration%len(lengths)]
    sets=[list(range(100-count,100)),sorted(rng.sample(range(100),count)),list(range(count))]
    mask=T([[int(j in inds) for j in range(100)] for inds in sets])
    item={n:T([[rng.randrange(0,9) for _ in range(101)] for _ in range(3)]) for n in names}
    for b in range(3):item['action'].rows[b][-1]=0
    tasks=[T([[rng.randrange(2) if mask.rows[b][j] else 0 for j in range(100)] for b in range(3)]) for _ in range(4)]
    # Explicit long ties, action-only differences, eligibility-only differences,
    # full palindromes and periodic sequences.
    if iteration%6 in [0,1,2,3]:
        for b,inds in enumerate(sets):
            seq=[tuple(rng.randrange(4) for _ in range(11)) for j in inds]
            if iteration%6==0:seq=[(1,)*7+(0,)*4 for _ in inds]
            if iteration%6==1:seq=[(1,)*6+(j%3,)+(0,)*4 for j in range(len(inds))]
            if iteration%6==2:seq=[(1,)*7+(j%2,0,0,0) for j in range(len(inds))]
            if iteration%6==3:
                for j in range(len(seq)//2):seq[-1-j]=seq[j]
            for j,tup in zip(inds,seq):
                for k,n in enumerate(names):item[n].rows[b][j]=tup[k]
                for k in range(4):tasks[k].rows[b][j]=tup[7+k]
    original=copy.deepcopy((item,mask,tasks))
    results={}
    for layout in ['path','dihedral','lexical','supplied']:
        result=execute(new,layout,item,mask,tasks);results[layout]=result
        out,elig=result
        for b,inds in enumerate(sets):
            seq=tuples(item,tasks,b,inds);got=tuples(out,elig,b,inds)
            if layout=='path':expected=min(seq,list(reversed(seq)))
            elif layout=='dihedral':
                choices=[seq[k:]+seq[:k] for k in range(len(seq))]
                rev=list(reversed(seq));choices += [rev[k:]+rev[:k] for k in range(len(rev))]
                expected=min(choices) if choices else []
            elif layout=='lexical':expected=sorted(seq)
            else:expected=seq
            assert got==expected,(iteration,layout,b)
            assert Counter(got)==Counter(seq)
            for n in names:
                assert out[n].rows[b][-1]==item[n].rows[b][-1]
                for j in range(100):
                    if j not in inds:assert out[n].rows[b][j]==item[n].rows[b][j]
            for k in range(4):
                for j in range(100):
                    if j not in inds:assert elig[k].rows[b][j]==tasks[k].rows[b][j]
            checks['brute_force_row_layout_matches']+=1
        again=execute(new,layout,out,mask,elig)
        assert compare(result,again);checks['idempotence_batches']+=1
        if layout!='path':
            assert compare(result,execute(old,layout,item,mask,tasks))
            checks['ancestor_bridge_batches']+=1
    assert all(item[n].rows==original[0][n].rows for n in names)
    assert mask.rows==original[1].rows
    assert all(a.rows==b.rows for a,b in zip(tasks,original[2]))
    # Reversal, arbitrary rotation, reversal+rotation and random valid permutation.
    for treatment in ['reverse','rotate','reverse_rotate','shuffle']:
        ti=copy.deepcopy(item);tt=copy.deepcopy(tasks)
        for b,inds in enumerate(sets):
            order=list(inds)
            if treatment in ['reverse','reverse_rotate']:order.reverse()
            if treatment in ['rotate','reverse_rotate'] and order:
                cut=rng.randrange(len(order));order=order[cut:]+order[:cut]
            if treatment=='shuffle':rng.shuffle(order)
            for dst,src in zip(inds,order):
                for n in names:ti[n].rows[b][dst]=item[n].rows[b][src]
                for k in range(4):tt[k].rows[b][dst]=tasks[k].rows[b][src]
        for layout in ['path','dihedral','lexical']:
            transformed=execute(new,layout,ti,mask,tt)
            equal=compare(results[layout],transformed)
            required=(layout=='lexical' or layout=='dihedral' and treatment!='shuffle' or layout=='path' and treatment=='reverse')
            if required:assert equal,(iteration,layout,treatment);checks['required_invariance_batches']+=1
            elif not equal:distinguish[layout+'_'+treatment]+=1
    # Invalid IDs and task eligibility cannot affect any valid-event ordering.
    ti=copy.deepcopy(item);tt=copy.deepcopy(tasks)
    for b,inds in enumerate(sets):
        for j in range(100):
            if j not in inds:
                for n in names:ti[n].rows[b][j]=10**12+rng.randrange(1000)
                for k in range(4):tt[k].rows[b][j]=rng.randrange(2)
    for layout in ['path','dihedral','lexical','supplied']:
        out,elig=execute(new,layout,ti,mask,tt)
        for b,inds in enumerate(sets):
            assert tuples(out,elig,b,inds)==tuples(*results[layout],b,inds)
        checks['invalid_perturbation_batches']+=1
assert distinguish['path_rotate'] and distinguish['path_shuffle'] and distinguish['dihedral_shuffle']
